package vn.boardinghub.modules.property;import vn.boardinghub.shared.exception.BusinessException;import vn.boardinghub.modules.audit.AuditService;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.List;
@Service public class PropertyService{private final PropertyRepository repo;private final AuditService audit;public PropertyService(PropertyRepository r,AuditService a){repo=r;audit=a;}public List<PropertyDtos.Response> list(){return repo.findAll().stream().map(PropertyDtos::from).toList();}public PropertyDtos.Response get(Long id){return PropertyDtos.from(find(id));}@Transactional public PropertyDtos.Response create(PropertyDtos.Request r){Property p=repo.save(new Property(r.name(),r.address(),r.description()));audit.record(actor(),"CREATE","PROPERTY",p.getId().toString(),p.getName());return PropertyDtos.from(p);}@Transactional public PropertyDtos.Response update(Long id,PropertyDtos.Request r){Property p=find(id);p.update(r.name(),r.address(),r.description());audit.record(actor(),"UPDATE","PROPERTY",id.toString(),p.getName());return PropertyDtos.from(p);}@Transactional public void delete(Long id){Property p=find(id);audit.record(actor(),"DELETE","PROPERTY",id.toString(),p.getName());repo.delete(p);}private String actor(){var a=SecurityContextHolder.getContext().getAuthentication();return a==null?"system":a.getName();}private Property find(Long id){return repo.findById(id).orElseThrow(()->BusinessException.notFound("Property"));}}
